package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class ReferenceType_getGenericSignature_TriageGen1Test {

    @Test
    public void testGetGenericSignature_Success() {
        // Arrange
        Class<?> cls = String.class;
        JavaType mockReferencedType = mock(JavaType.class);

        // We use the static factory method available in the class
        ReferenceType referenceType = ReferenceType.construct(cls, mockReferencedType, null, null);

        StringBuilder sb = new StringBuilder("Initial");

        // Mocking the behavior of the referenced type's getGenericSignature
        // The method being tested calls: sb = _referencedType.getGenericSignature(sb);
        when(mockReferencedType.getGenericSignature(any(StringBuilder.class))).thenAnswer(invocation -> {
            StringBuilder argumentSb = invocation.getArgument(0);
            argumentSb.append("MockedType");
            return argumentSb;
        });

        // Act
        StringBuilder result = referenceType.getGenericSignature(sb);

        // Assert
        // Expected flow:
        // 1. _classSignature called (appends class signature to sb)
        // 2. sb.append('<')
        // 3. _referencedType.getGenericSignature(sb) called

        // Since _classSignature is protected and implementation details depend on internal state,
        // we verify the sequence and the transformations.
        // For a standard ReferenceType, _classSignature usually appends the class name.

        // Verify the referenced type was indeed called with the StringBuilder containing '<'
        verify(mockReferencedType).getGenericSignature(Mockito.argThat(s -> s.toString().contains("<")));

        // Check if the return value is the same instance or updated content
        // Based on the code: sb = _referencedType.getGenericSignature(sb); return sb;
        // The result should contain the '<' and the mocked content.
        assertEquals("MockedType", result.substring(result.lastIndexOf("MockedType")));
    }

    @Test
    public void testGetGenericSignature_EmptyStringBuilder() {
        // Arrange
        Class<?> cls = Integer.class;
        JavaType mockReferencedType = mock(JavaType.class);
        ReferenceType referenceType = ReferenceType.construct(cls, mockReferencedType, null, null);

        StringBuilder sb = new StringBuilder();

        when(mockReferencedType.getGenericSignature(any(StringBuilder.class))).thenAnswer(invocation -> {
            StringBuilder argumentSb = invocation.getArgument(0);
            argumentSb.append("Ref");
            return argumentSb;
        });

        // Act
        StringBuilder result = referenceType.getGenericSignature(sb);

        // Assert
        // Result should contain '<' and 'Ref'
        // _classSignature for Integer.class will append something, then '<', then 'Ref'
        String resultStr = result.toString();
        org.junit.Assert.assertTrue(resultStr.contains("<"));
        org.junit.Assert.assertTrue(resultStr.contains("Ref"));
    }
}
